head.b:skin:
:root{--green:#123b30;--green2:#1b5845;--gold:#e2b85e;--paper:#f7f8f5;--ink:#17231d;--muted:#69776f;--white:#fff}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 system-ui,-apple-system,"Segoe UI",sans-serif}
a{color:inherit;text-decoration:none}.wrap{width:min(1080px,92%);margin:auto}
header{background:var(--green);color:white;padding:15px 0;position:sticky;top:0;z-index:10}.head{display:flex;justify-content:space-between;align-items:center;gap:12px}.brand{font-weight:900;letter-spacing:.3px}.brand span{color:var(--gold)}.admin{font-size:.85rem;border:1px solid #ffffff55;padding:8px 12px;border-radius:10px}
.hero{background:linear-gradient(125deg,#102f28,#24624b);color:white;padding:35px 0 30px}.hero h1{font-size:clamp(1.8rem,5vw,3rem);line-height:1.1;margin:8px 0}.hero p{color:#dce9e1;max-width:650px;margin:8px 0}.eyebrow{font-size:.76rem;letter-spacing:1.4px;color:var(--gold);font-weight:800;text-transform:uppercase}
main{padding:24px 0 55px}.panel{background:white;border:1px solid #e6ece7;border-radius:18px;padding:18px;margin:0 0 18px;box-shadow:0 5px 20px #123b300b}.section-title{margin:0 0 5px;color:var(--green);font-size:1.25rem}.muted{color:var(--muted);font-size:.92rem}
.gender{position:fixed;inset:0;background:#0b211bd9;z-index:50;display:grid;place-items:center;padding:20px}.gender-box{background:#fff;color:var(--ink);width:min(430px,100%);border-radius:22px;padding:26px;text-align:center}.gender-box h2{margin:0 0 8px;color:var(--green)}.gender-actions{display:flex;gap:12px;margin-top:20px}.gender-actions button{flex:1}
.btn{border:0;border-radius:12px;background:var(--gold);color:#1b2b22;font-weight:850;padding:12px 16px;font:inherit;cursor:pointer}.btn.green{background:var(--green);color:white}.btn.ghost{background:#e8f1eb;color:var(--green)}.btn:disabled{opacity:.5;cursor:not-allowed}
.schedule-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.schedule-box{background:#f3f7f3;border-radius:14px;padding:14px}.schedule-box strong{display:block;color:var(--green);font-size:1.04rem}.countdown{font-size:1.45rem;font-weight:900;color:var(--green);font-variant-numeric:tabular-nums;margin-top:6px}
.livebox{background:#0b1713;color:white;border-radius:18px;padding:20px;text-align:center;overflow:hidden}.livebox h2{margin:5px 0;color:white}.live-label{color:#f1c969;font-size:.76rem;letter-spacing:2px;font-weight:900}.wave{height:58px;display:flex;align-items:center;justify-content:center;gap:4px;margin:10px 0}.wave i{display:block;width:5px;height:14px;background:#d9b45e;border-radius:5px;animation:wave .8s ease-in-out infinite alternate}.wave i:nth-child(3n){animation-delay:.2s}.wave i:nth-child(2n){animation-delay:.4s}@keyframes wave{to{height:48px}}
.story-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.story{background:#fff;border:1px solid #e6ece7;border-radius:16px;overflow:hidden}.cover{height:135px;background:linear-gradient(135deg,#e7d4a7,#f5ead0);display:grid;place-items:center;font-size:3rem}.cover img{width:100%;height:100%;object-fit:cover}.storybody{padding:14px}.tag{display:inline-block;background:#e9f2eb;color:var(--green);font-size:.75rem;border-radius:30px;padding:3px 9px;font-weight:800}.story h3{font-size:1.03rem;margin:9px 0 5px}.story p{font-size:.9rem;color:var(--muted);margin:0 0 12px}
#history{display:grid;gap:9px}.past{border:1px solid #e6ece7;padding:12px;border-radius:12px;display:flex;justify-content:space-between;align-items:center;gap:12px}.past small{display:block;color:var(--muted)}
footer{background:#102f28;color:#dbe7df;padding:24px 0;font-size:.9rem}
.hidden{display:none!important}
@media(max-width:700px){.schedule-grid{grid-template-columns:1fr 1fr}.story-grid{grid-template-columns:1fr 1fr}.hero{padding:27px 0}.past{align-items:flex-start;flex-direction:column}}
@media(max-width:420px){.story-grid{grid-template-columns:1fr}.gender-actions{flex-direction:column}}

body.script:
//
(function(){
'use strict';
const SUPABASE_URL='https://djnythtnrzppgxprwvyu.supabase.co';
const SUPABASE_KEY='sb_publishable_IDe42Bp4DK6lqrkZcaXhpA_vdh2IA-t';
const $=id=>document.getElementById(id);
const gate=$('genderGate'),audio=$('radioAudio');
$('year').textContent=new Date().getFullYear();
function setGender(g){try{localStorage.setItem('shafa_gender',g)}catch(e){}gate.classList.add('hidden')}
let saved='';try{saved=localStorage.getItem('shafa_gender')||''}catch(e){}
if(saved==='male'||saved==='female')gate.classList.add('hidden');
$('maleBtn').onclick=()=>setGender('male');$('femaleBtn').onclick=()=>setGender('female');
let client=null,shows=[],allEpisodes=[],active=null,next=null,activeStart=0,activeEnd=0,playing=false;
function lagosNow(){return new Date(new Date().toLocaleString('en-US',{timeZone:'Africa/Lagos'}))}
function scheduleStart(s,now){if(!s.repeat_daily)return new Date(s.starts_at).getTime();const p=(s.local_time||'00:00').split(':').map(Number),d=lagosNow();d.setHours(p[0],p[1],0,0);return now+(d.getTime()-lagosNow().getTime())}
function timeLabel(t){return new Intl.DateTimeFormat('ha-NG',{hour:'numeric',minute:'2-digit',hour12:true,timeZone:'Africa/Lagos'}).format(new Date(t))}
function getSchedule(ep){return (ep.schedules||[]).map(s=>({ep,s,start:scheduleStart(s,Date.now())})).filter(x=>x.start<=Date.now()&&Date.now()-x.start<86400000).sort((a,b)=>b.start-a.start)[0]||null}
function getNext(){let list=[];allEpisodes.forEach(ep=>(ep.schedules||[]).forEach(s=>{let t=scheduleStart(s,Date.now());if(s.repeat_daily&&t<=Date.now())t+=86400000;if(t>Date.now())list.push({ep,s,start:t})}));list.sort((a,b)=>a.start-b.start);return list[0]||null}
function showTitle(ep){return ep?(ep.title||'Shirin rediyo'):'Shirin rediyo'}
function makeCard(story){const el=document.createElement('article');el.className='story';const cover=document.createElement('div');cover.className='cover';if(story.cover_url){const im=document.createElement('img');im.src=story.cover_url;im.alt=story.title;cover.appendChild(im)}else cover.textContent='📚';const body=document.createElement('div');body.className='storybody';const tag=document.createElement('span');tag.className='tag';tag.textContent=story.category||'Labarai';const h=document.createElement('h3');h.textContent=story.title;const p=document.createElement('p');p.textContent=story.summary||'Shirin labari a Hausa.';const b=document.createElement('button');b.className='btn ghost';b.textContent='Duba shirye-shirye';b.onclick=()=>renderStoryEpisodes(story);body.append(tag,h,p,b);el.append(cover,body);return el}
function renderStoryEpisodes(story){const found=allEpisodes.filter(e=>e.story_id===story.id);const box=document.createElement('div');box.className='panel';const h=document.createElement('h3');h.textContent=story.title;box.appendChild(h);if(!found.length){box.append('Ba a saka shiri ba tukuna.')}found.forEach(ep=>{const row=document.createElement('div');row.className='past';const name=document.createElement('div');name.textContent=ep.title||('Babi '+ep.episode_number);const b=document.createElement('button');b.className='btn ghost';b.textContent='Saurara';b.onclick=()=>playEpisode(ep,null);row.append(name,b);box.append(row)});const old=document.getElementById('selectedStory');if(old)old.remove();box.id='selectedStory';$('stories').after(box);box.scrollIntoView({behavior:'smooth'})}
function addHistory(ep,stamp){const row=document.createElement('div');row.className='past';const info=document.createElement('div');const strong=document.createElement('strong');strong.textContent=showTitle(ep);const small=document.createElement('small');small.textContent='Shirin da ya gabata · '+timeLabel(stamp);info.append(strong,small);const b=document.createElement('button');b.className='btn ghost';b.textContent='Saurara daga farko';b.onclick=()=>playEpisode(ep,null,true);row.append(info,b);$('history').append(row)}
function playEpisode(ep,startAt,fromBeginning){if(!ep.audio_url){$('liveMessage').textContent='Ba a ɗora MP3 na wannan shiri ba tukuna.';return}active=ep;activeStart=startAt||Date.now();activeEnd=activeStart+((ep.duration_seconds||0)*1000);$('liveTitle').textContent=showTitle(ep);$('livePanel').classList.remove('hidden');audio.src=ep.audio_url;audio.controls=false;audio.currentTime=0;audio.load();audio.onloadedmetadata=()=>{if(startAt&&!fromBeginning){const elapsed=Math.max(0,(Date.now()-startAt)/1000);if(elapsed<audio.duration)audio.currentTime=elapsed;else{$('liveMessage').textContent='Wannan shirin ya ƙare. Duba shirye-shiryen da suka gabata.';return}}audio.play().then(()=>{$('liveMessage').textContent='Kana sauraron Muryar Mustapha';$('playBtn').textContent='⏸ Dakata';playing=true}).catch(()=>{$('liveMessage').textContent='Domin dokar browser, danna Fara Sauraro domin kunna rediyo.';$('playBtn').textContent='▶ Fara Sauraro'})};audio.onended=()=>{$('liveMessage').textContent='An kammala shirin. Za a dawo da kai shafin farko.';$('livePanel').classList.add('hidden');playing=false;active=null}}
$('playBtn').onclick=()=>{if(!audio.src)return;if(audio.paused){if(activeStart&&active){const offset=(Date.now()-activeStart)/1000;if(Number.isFinite(audio.duration)&&offset<audio.duration)audio.currentTime=offset}audio.play().then(()=>{$('playBtn').textContent='⏸ Dakata';playing=true}).catch(()=>{$('liveMessage').textContent='Ba a iya kunna sautin ba. Sake gwadawa.'})}else{audio.pause();$('playBtn').textContent='▶ Ci gaba';playing=false}};
function refreshClock(){const now=Date.now();active=null;allEpisodes.forEach(ep=>{const a=getSchedule(ep);if(a&&(!active||a.start>active.start))active={...a}});next=getNext();if(active){$('programName').textContent=showTitle(active.ep);$('nextTime').textContent='Yana gudana yanzu';$('countdown').textContent='LIVE';$('programStatus').textContent='An fara '+timeLabel(active.start);if(active.ep.audio_url&&(!audio.src||!audio.src.includes(active.ep.audio_url))){$('livePanel').classList.remove('hidden');playEpisode(active.ep,active.start,false)}else $('livePanel').classList.remove('hidden')}else if(next){$('programName').textContent=showTitle(next.ep);$('nextTime').textContent=timeLabel(next.start);$('programStatus').textContent='Ana jiran farawa';const diff=Math.max(0,next.start-now),h=Math.floor(diff/3600000),m=Math.floor(diff%3600000/60000),s=Math.floor(diff%60000/1000);$('countdown').textContent=[h,m,s].map(x=>String(x).padStart(2,'0')).join(':')}else{$('programName').textContent='Ba a tsara shiri na gaba ba';$('nextTime').textContent='Ba a saita ba';$('countdown').textContent='--:--:--'}const repeat=allEpisodes.flatMap(ep=>(ep.schedules||[]).filter(s=>s.repeat_daily).map(s=>s.local_time)).sort()[0];$('repeatTime').textContent=repeat||'Ba a saita ba'}
async function init(){try{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2';script.onload=async()=>{try{client=window.supabase.createClient(SUPABASE_URL,SUPABASE_KEY);const {data,error}=await client.from('shafa_stories').select('id,title,slug,summary,category,cover_url').eq('status','published').order('created_at',{ascending:false});if(error)throw error;shows=data||[];$('stories').replaceChildren();shows.forEach(s=>$('stories').append(makeCard(s)));$('history').replaceChildren();for(const story of shows){const {data:eps,error:e}=await client.rpc('get_shafa_episode_catalog',{p_story_id:story.id});if(e)continue;(eps||[]).forEach(ep=>{ep.story_id=story.id;allEpisodes.push(ep);const activeSlot=getSchedule(ep);if(activeSlot&&ep.audio_url)addHistory(ep,activeSlot.start-86400000)})}refreshClock();setInterval(refreshClock,1000)}catch(e){$('programName').textContent='An samu matsala wajen haɗa shirye-shirye.';$('stories').textContent='Sake buɗe shafin idan intanet ya dawo.';console.error(e)}};script.onerror=()=>{$('programName').textContent='Ba a samu haɗin Supabase ba.'};document.head.appendChild(script)}catch(e){console.error(e)}}
init();
})();
//
